import{_ as e}from"./chunks/image2.CJY56ln_.js";import{_ as o,o as n,c as r,am as i}from"./chunks/framework.BUK3Qdpn.js";const a="/projects/Tankbot/en/tankbotaI/assets/image3.2g2dprSH.webp",s="/projects/Tankbot/en/tankbotaI/assets/image4.ehvNU26P.webp",l="data:image/png;base64,",c="/projects/Tankbot/en/tankbotaI/assets/image5.D7g9kAJ-.webp",d="/projects/Tankbot/en/tankbotaI/assets/image2.BS7RYPyL.webp",g="/projects/Tankbot/en/tankbotaI/assets/image6.K3JuhGVf.webp",p="/projects/Tankbot/en/tankbotaI/assets/imageaa.0egBgbWP.webp",h="/projects/Tankbot/en/tankbotaI/assets/image8.DO820EXh.webp",m="data:image/png;base64,",b="/projects/Tankbot/en/tankbotaI/assets/image10.DRtEkQpu.webp",u="/projects/Tankbot/en/tankbotaI/assets/image11.CjlOFK9W.webp",x="/projects/Tankbot/en/tankbotaI/assets/image12.CNL4l9Xo.webp",y="/projects/Tankbot/en/tankbotaI/assets/image13.thWp8xmp.webp",k="/projects/Tankbot/en/tankbotaI/assets/image14.C3CkD5NE.webp",A="/projects/Tankbot/en/tankbotaI/assets/image15.BxNOk-p0.webp",I="/projects/Tankbot/en/tankbotaI/assets/image16.DkPMzd82.webp",w="/projects/Tankbot/en/tankbotaI/assets/image17.CV8reOIa.webp",C="/projects/Tankbot/en/tankbotaI/assets/image18.Csw__jAf.webp",f="/projects/Tankbot/en/tankbotaI/assets/image19.CL_681hX.webp",E="/projects/Tankbot/en/tankbotaI/assets/image20.dGf7TCaf.webp",T="/projects/Tankbot/en/tankbotaI/assets/image21.2OYDb82Z.webp",B="/projects/Tankbot/en/tankbotaI/assets/image23.B8Vt2YAr.webp",v="/projects/Tankbot/en/tankbotaI/assets/image24.Betwc2Cf.webp",R="/projects/Tankbot/en/tankbotaI/assets/image1.Bw5DvhlJ.webp",D="/projects/Tankbot/en/tankbotaI/assets/image6.DWXDkpwX.webp",X=JSON.parse('{"title":"2. Remote Control","description":"","frontmatter":{},"headers":[],"relativePath":"docs/2. Remote Control.md","filePath":"docs/2. Remote Control.md"}'),U={name:"docs/2. Remote Control.md"};function S(q,t,z,Q,j,G){return n(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="_2-remote-control" tabindex="-1">2. Remote Control <a class="header-anchor" href="#_2-remote-control" aria-label="Permalink to &quot;2. Remote Control&quot;">​</a></h1><p>[TOC]</p><h2 id="_2-1-mobile-app-control" tabindex="-1">2.1 Mobile App Control <a class="header-anchor" href="#_2-1-mobile-app-control" aria-label="Permalink to &quot;2.1 Mobile App Control&quot;">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The Tankbot factory program includes app control, which can be experienced immediately after power-on.</strong></p></div><h3 id="_2-1-1-mobile-app-installation" tabindex="-1">2.1.1 Mobile App Installation <a class="header-anchor" href="#_2-1-1-mobile-app-installation" aria-label="Permalink to &quot;2.1.1 Mobile App Installation&quot;">​</a></h3><p>Apple users can download the app by searching for <strong>Wonderbot</strong> in the App Store.</p><p>Android users can scan the QR code below to download, or go to <a href="https://drive.google.com/drive/folders/1Lsr_VqCEv4Wq9Okv0eBGHTK-x6EZjtlb?usp=sharing" target="_blank" rel="noreferrer"><strong>Software Tools &amp; Program Suite</strong></a> to locate the <strong>Wonderbot</strong> installation package and install it on the phone.</p><img loading="lazy" height="214" width="218" class="common_img" src="'+a+'"><h3 id="_2-1-2-mobile-app-connection" tabindex="-1">2.1.2 Mobile App Connection <a class="header-anchor" href="#_2-1-2-mobile-app-connection" aria-label="Permalink to &quot;2.1.2 Mobile App Connection&quot;">​</a></h3><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ul><li><p><strong>Before using the Wonderbot app, enable Bluetooth and location services in the phone settings.</strong></p></li><li><p><strong>Pair and connect with the device through the Bluetooth button in the app. Do not pair through a passkey in the phone settings.</strong></p></li></ul></div><ol><li>Turn on the device power switch.</li></ol><img loading="lazy" height="636" src="'+s+'" width="600px" class="common_img"><ol start="2"><li>Open the mobile app <strong>Wonderbot</strong>, tap the <img loading="lazy" height="78" src="'+l+'" width="50px" class="inline-icon"> icon in the upper-left corner to select the robot type, and choose <strong>Tankbot</strong> here.</li></ol><img loading="lazy" height="1260" src="'+c+'" width="600px" class="common_img"><ol start="3"><li>After selection, enter the mode selection interface and tap <strong>Robot Control</strong> . Tap the flashing <img loading="lazy" height="97" src="'+d+'" width="50px" class="inline-icon"> icon in the upper right corner, find <strong>Hiwonder</strong> in the Bluetooth list, and then tap it for connection.</li></ol><img loading="lazy" height="1260" src="'+g+'" width="600px" class="common_img"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>If no Hiwonder-related name appears initially, tap Search Again to search for the device.</strong></p></div><ol start="4"><li>After successful connection, the Bluetooth icon in the upper right corner remains lit.</li></ol><img loading="lazy" height="1260" src="'+p+'" width="600px" class="common_img"><h3 id="_2-1-3-introduction-to-app-functions" tabindex="-1">2.1.3 Introduction to App Functions <a class="header-anchor" href="#_2-1-3-introduction-to-app-functions" aria-label="Permalink to &quot;2.1.3 Introduction to App Functions&quot;">​</a></h3><ul><li><strong>Control Interface Overview</strong></li></ul><p>After entering the control interface, the robot movement can be controlled via buttons and sliders. The interface is divided into two parts, as shown in the figure below.</p><img loading="lazy" height="1266" src="'+h+'" width="600px" class="common_img"><p>① Menu Bar</p><table tabindex="0"><thead><tr><th style="text-align:center;">Icon</th><th style="text-align:center;">Function</th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="82" src="'+m+'" width="100px"></td><td style="text-align:center;">Returns to the main interface to select the robot type</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="80" src="'+b+'" width="100px"></td><td style="text-align:center;">Displays the current battery voltage</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="97" src="'+u+'" width="100px"></td><td style="text-align:center;">Enables image transmission</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="94" src="'+x+'" width="100px"></td><td style="text-align:center;">Bluetooth connection status. The icon blinks when disconnected and stays solid when connected</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="79" src="'+y+'" width="100px"></td><td style="text-align:center;">More information</td></tr></tbody></table><p>② Control Area</p><table tabindex="0"><thead><tr><th style="text-align:center;">Icon</th><th style="text-align:center;">Function</th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="324" src="'+k+'" width="200px"></td><td style="text-align:center;">Controls chassis movement</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="234" src="'+A+'" width="200px"></td><td style="text-align:center;">Controls chassis steering</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="140" src="'+I+'" width="200px"></td><td style="text-align:center;">Controls chassis movement via the built-in gyroscope of the mobile phone</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="195" src="'+w+'" width="300px"></td><td style="text-align:center;">Controls chassis speed</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="145" src="'+C+'" width="300px"></td><td style="text-align:center;">Controls rotation of a single servo on the robotic arm</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="297" src="'+f+'" width="200px"></td><td style="text-align:center;">Controls the robotic arm to execute action groups</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="142" src="'+E+'" width="200px"></td><td style="text-align:center;">Controls the robotic arm to return to its initial posture</td></tr></tbody></table><ul><li><strong>Introduction to Custom Action Groups</strong></li></ul><p>The app provides six action group execution commands. Execution commands for other action groups can be added as follows:</p><ol><li>Tap the action icon, then tap the <strong>Add</strong> button in the lower-right corner.</li></ol><img loading="lazy" src="'+T+'" width="500px" class="common_img"><ol start="2"><li>In <strong>Add Action</strong>, enter the action group name and number, then tap <strong>Ok</strong>.</li></ol><img loading="lazy" height="1260" src="'+B+'" width="500px" class="common_img"><ol start="3"><li>Once the addition is complete, the new action group appears in the action group list. Tap it to run.</li></ol><img loading="lazy" height="1260" src="'+v+'" width="500px" class="common_img"><h2 id="_2-2-wireless-controller-control" tabindex="-1">2.2 Wireless Controller Control <a class="header-anchor" href="#_2-2-wireless-controller-control" aria-label="Permalink to &quot;2.2 Wireless Controller Control&quot;">​</a></h2><h3 id="_2-2-1-preparation" tabindex="-1">2.2.1 Preparation <a class="header-anchor" href="#_2-2-1-preparation" aria-label="Permalink to &quot;2.2.1 Preparation&quot;">​</a></h3><ol><li>Ensure the controller receiver is inserted into the control board, as shown below:</li></ol><img loading="lazy" height="800" class="common_img" src="'+e+'" width="600px"><ol start="2"><li>Remove the back cover of the wireless controller and insert two AAA batteries into the battery compartment. Ensure the positive and negative terminals are not reversed.</li></ol><img loading="lazy" height="463" class="common_img" src="'+R+'" width="600px"><h3 id="_2-2-2-device-connection" tabindex="-1">2.2.2 Device Connection <a class="header-anchor" href="#_2-2-2-device-connection" aria-label="Permalink to &quot;2.2.2 Device Connection&quot;">​</a></h3><ol><li>Push the device power switch to <strong>ON</strong>, then briefly press the onboard <strong>KEY1</strong> button twice. The buzzer will sound three times, indicating that the wireless controller control mode has been entered.</li></ol><img loading="lazy" height="396" class="common_img" src="'+D+'" width="400px"><ol start="2"><li><p>Turn on the wireless controller power switch, and both the red and green LED lights will blink simultaneously.</p></li><li><p>Wait a few seconds, and the robotic arm will automatically pair with the wireless controller. After successful pairing, the red and green LEDs will stay solidly lit. If only one green or one red LED is lit after power-on, press the <strong>MODE</strong> key.</p></li><li><p>If the connection is not successful, turn off the robotic arm and the wireless controller first, then repeat the above steps.</p></li></ol><p>Sleep Mode: If the wireless controller is not connected to the robotic arm within 30 seconds after power-on, or no operation is performed on the wireless controller within five minutes after connection, the wireless controller enters sleep mode. To wake the wireless controller, press the <strong>START</strong> button.</p><h3 id="_2-2-3-button-description" tabindex="-1">2.2.3 Button Description <a class="header-anchor" href="#_2-2-3-button-description" aria-label="Permalink to &quot;2.2.3 Button Description&quot;">​</a></h3><p>The following table describes the functions of buttons of the wireless controller.</p><table tabindex="0"><thead><tr><th style="text-align:center;">Button</th><th style="text-align:center;">Function</th></tr></thead><tbody><tr><td style="text-align:center;">Left joystick up</td><td style="text-align:center;">Forward</td></tr><tr><td style="text-align:center;">Left joystick down</td><td style="text-align:center;">Backward</td></tr><tr><td style="text-align:center;">Right joystick left</td><td style="text-align:center;">Turn left</td></tr><tr><td style="text-align:center;">Right joystick right</td><td style="text-align:center;">Turn right</td></tr><tr><td style="text-align:center;">START</td><td style="text-align:center;">All servos return to initial posture</td></tr><tr><td style="text-align:center;">Y</td><td style="text-align:center;">Close servo ID1</td></tr><tr><td style="text-align:center;">A</td><td style="text-align:center;">Open servo ID1</td></tr><tr><td style="text-align:center;">X</td><td style="text-align:center;">Rotate servo ID2 left</td></tr><tr><td style="text-align:center;">B</td><td style="text-align:center;">Rotate servo ID2 right</td></tr><tr><td style="text-align:center;">R2</td><td style="text-align:center;">Rotate servo ID3 forward</td></tr><tr><td style="text-align:center;">R1</td><td style="text-align:center;">Rotate servo ID3 backward</td></tr><tr><td style="text-align:center;">L2</td><td style="text-align:center;">Rotate servo ID4 forward</td></tr><tr><td style="text-align:center;">L1</td><td style="text-align:center;">Rotate servo ID4 backward</td></tr><tr><td style="text-align:center;"><kbd>↑</kbd></td><td style="text-align:center;">Rotate servo ID5 forward</td></tr><tr><td style="text-align:center;"><kbd>↓</kbd></td><td style="text-align:center;">Rotate servo ID5 backward</td></tr><tr><td style="text-align:center;"><kbd>←</kbd>←</td><td style="text-align:center;">Rotate servo ID6 left</td></tr><tr><td style="text-align:center;"><kbd>→</kbd></td><td style="text-align:center;">Rotate servo ID6 right</td></tr><tr><td style="text-align:center;">SELECT + ↑<kbd>↑</kbd></td><td style="text-align:center;">Execute action group 0</td></tr><tr><td style="text-align:center;">SELECT + ↓<kbd>↓</kbd></td><td style="text-align:center;">Execute action group 1</td></tr><tr><td style="text-align:center;">SELECT + ←<kbd>←</kbd>←</td><td style="text-align:center;">Execute action group 2</td></tr><tr><td style="text-align:center;">SELECT + <kbd>→</kbd></td><td style="text-align:center;">Execute action group 3</td></tr><tr><td style="text-align:center;">SELECT + L1</td><td style="text-align:center;">Execute action group 4</td></tr><tr><td style="text-align:center;">SELECT + L2</td><td style="text-align:center;">Execute action group 5</td></tr><tr><td style="text-align:center;">SELECT + Y</td><td style="text-align:center;">Execute action group 6</td></tr></tbody></table>',49)])])}const F=o(U,[["render",S]]);export{X as __pageData,F as default};
